"""Stark World Engine shared helpers for the UE5 editor scripts (UE 5.4+). Generated by Stark World Engine; safe to edit.

Every editor API used here is from the Unreal Python API reference (UE 5.4):
  https://dev.epicgames.com/documentation/en-us/unreal-engine/python-api/?application_version=5.4
Coordinates: Stark World Engine plans are metres with y up and x/z on the ground. Unreal is centimetres with Z up. The mapping keeps
the layout un-mirrored: UE X = -z, UE Y = x, UE Z = y, and actor yaw (UE) = plan yaw (StarkTypes.h does the same).
"""
import csv, hashlib, json, math, os, struct, wave, zlib
import unreal

HERE = os.path.dirname(os.path.abspath(__file__))
PROJECT = os.path.dirname(os.path.dirname(HERE))
SAVED = os.path.join(PROJECT, "Saved", "Stark")
ART_SRC = os.path.join(PROJECT, "StarkAssets")
DATA_DIR = os.path.join(PROJECT, "Content", "Stark", "Data")
ROOT = "/Game/Stark"
MAPS = ROOT + "/Maps"
SHAPES = {"cube": "/Engine/BasicShapes/Cube.Cube", "cylinder": "/Engine/BasicShapes/Cylinder.Cylinder",
          "cone": "/Engine/BasicShapes/Cone.Cone", "sphere": "/Engine/BasicShapes/Sphere.Sphere",
          "plane": "/Engine/BasicShapes/Plane.Plane"}
INSTANCE_MIN = 40          # classes with at least this many objects are placed as one instanced actor per part
TILE = 200.0               # 2.5D chapters: one browser tile (32 px) = 2 m
REPORT = {"warnings": [], "counts": {}, "levels": []}
BUILD_VERSION = "stark-build/2"


def log(msg):
    unreal.log("[StarkWorldEngine] " + str(msg))


def warn(msg):
    REPORT["warnings"].append(str(msg))
    unreal.log_warning("[StarkWorldEngine] " + str(msg))


def load_json(path):
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def load_plans():
    """-> list of per-level visual plans (stark_plan.json format 2; format 1 = one level)."""
    d = load_json(os.path.join(HERE, "stark_plan.json"))
    return d["levels"] if isinstance(d, dict) and "levels" in d else [d]


def load_plan(level=0):
    plans = load_plans()
    return plans[level] if 0 <= level < len(plans) else plans[0]


def load_game():
    p = os.path.join(DATA_DIR, "stark_game.json")
    return load_json(p) if os.path.isfile(p) else {}


def load_game_ue_text():
    p = os.path.join(DATA_DIR, "stark_game_ue.json")
    with open(p, encoding="utf-8") as f:
        return f.read()


def content_hash():
    h = hashlib.sha256(BUILD_VERSION.encode())
    for p in (os.path.join(DATA_DIR, "stark_game.json"), os.path.join(HERE, "stark_plan.json"),
              os.path.join(HERE, "proxy_swap_map.csv"), os.path.join(HERE, "metahuman_slots.csv"),
              os.path.join(HERE, "stark_assets.json")):
        if os.path.isfile(p):
            with open(p, "rb") as f:
                h.update(f.read())
    return h.hexdigest()


def runtime_ready():
    """True when the Stark World Engine Runtime C++ plugin is loaded (its classes exist in Python)."""
    return all(hasattr(unreal, n) for n in ("StarkInteractable", "StarkEnemyCharacter", "StarkNpcCharacter",
                                            "StarkGameData", "StarkEditorLibrary"))


def setp(obj, name, value):
    try:
        obj.set_editor_property(name, value)
        return True
    except Exception as e:
        warn("%s.%s: %s" % (type(obj).__name__, name, e))
        return False


def lin(rgb, mul=1.0):
    """sRGB 0..1 -> unreal.LinearColor."""
    return unreal.LinearColor(*[(max(0.0, c) ** 2.2) * mul for c in rgb[:3]], 1.0)


def cm(x, y, z):
    """plan metres (x, up, z) -> UE centimetres: X = -z, Y = x, Z = y."""
    return unreal.Vector(-z * 100.0, x * 100.0, y * 100.0)


def tile_cm(col, row, rows):
    """2.5D chapter tile (column, row) centre -> UE centimetres (X along the run, Z up, Y = 0 plane)."""
    return unreal.Vector(col * TILE + TILE * 0.5, 0.0, (rows - 1 - row) * TILE + TILE * 0.5)


def rot(yaw=0.0, pitch=0.0, roll=0.0):
    return unreal.Rotator(roll=roll, pitch=pitch, yaw=yaw)


def actor_sub():
    return unreal.get_editor_subsystem(unreal.EditorActorSubsystem)


def level_sub():
    return unreal.get_editor_subsystem(unreal.LevelEditorSubsystem)


def spawn(cls, loc, rotation=None, label=None, folder=None, tags=(), always_loaded=False):
    a = actor_sub().spawn_actor_from_class(cls, loc, rotation or rot())
    if a is None:
        raise RuntimeError("could not spawn %s" % cls)
    if label:
        a.set_actor_label(label)
    if folder:
        a.set_folder_path(folder)
    setp(a, "tags", [unreal.Name("GS")] + [unreal.Name(t) for t in tags])
    if always_loaded:
        try:                                   # World Partition: keep gameplay actors loaded everywhere
            a.set_editor_property("is_spatially_loaded", False)
        except Exception:
            pass
    return a


def comp(actor, cls):
    try:
        return actor.get_component_by_class(cls)
    except Exception:
        return None


def gs_actors(tag="GS"):
    out = []
    for a in actor_sub().get_all_level_actors():
        try:
            if a.actor_has_tag(tag):
                out.append(a)
        except Exception:
            pass
    return out


def destroy(actors):
    for a in actors:
        try:
            actor_sub().destroy_actor(a)
        except Exception as e:
            warn("destroy: %s" % e)


def asset_tools():
    return unreal.AssetToolsHelpers.get_asset_tools()


def class_name(obj):
    try:
        return obj.get_class().get_name()
    except Exception:
        return ""


def load(path):
    try:
        return unreal.EditorAssetLibrary.load_asset(path) if unreal.EditorAssetLibrary.does_asset_exist(path) else None
    except Exception:
        return None


def new_asset(name, folder, cls, factory):
    path = folder + "/" + name
    a = load(path)
    if a is not None:
        return a
    return asset_tools().create_asset(name, folder, cls, factory)


# ---------------- materials
def master_material():
    path = ROOT + "/Materials/M_GS_Proxy"
    m = load(path)
    if m is not None:
        return m
    mel = unreal.MaterialEditingLibrary
    mat = asset_tools().create_asset("M_GS_Proxy", ROOT + "/Materials", unreal.Material, unreal.MaterialFactoryNew())
    setp(mat, "two_sided", True)
    base = mel.create_material_expression(mat, unreal.MaterialExpressionVectorParameter, -600, -200)
    setp(base, "parameter_name", "BaseColor")
    setp(base, "default_value", unreal.LinearColor(0.5, 0.5, 0.5, 1.0))
    mel.connect_material_property(base, "", unreal.MaterialProperty.MP_BASE_COLOR)
    rough = mel.create_material_expression(mat, unreal.MaterialExpressionScalarParameter, -600, 50)
    setp(rough, "parameter_name", "Roughness")
    setp(rough, "default_value", 0.85)
    mel.connect_material_property(rough, "", unreal.MaterialProperty.MP_ROUGHNESS)
    emis = mel.create_material_expression(mat, unreal.MaterialExpressionVectorParameter, -600, 200)
    setp(emis, "parameter_name", "Emissive")
    setp(emis, "default_value", unreal.LinearColor(0.0, 0.0, 0.0, 1.0))
    strength = mel.create_material_expression(mat, unreal.MaterialExpressionScalarParameter, -600, 400)
    setp(strength, "parameter_name", "EmissiveStrength")
    setp(strength, "default_value", 0.0)
    mul = mel.create_material_expression(mat, unreal.MaterialExpressionMultiply, -300, 300)
    mel.connect_material_expressions(emis, "", mul, "A")
    mel.connect_material_expressions(strength, "", mul, "B")
    mel.connect_material_property(mul, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    mel.recompile_material(mat)
    unreal.EditorAssetLibrary.save_loaded_asset(mat)
    return mat


def proxy_materials(plan):
    mel = unreal.MaterialEditingLibrary
    parent = master_material()
    out = {}
    for key, rgb in plan["materials"].items():
        path = ROOT + "/Materials/MI_GS_" + key
        mi = load(path)
        if mi is None:
            mi = asset_tools().create_asset("MI_GS_" + key, ROOT + "/Materials", unreal.MaterialInstanceConstant,
                                            unreal.MaterialInstanceConstantFactoryNew())
        mel.set_material_instance_parent(mi, parent)
        mel.set_material_instance_vector_parameter_value(mi, "BaseColor", lin(rgb))
        strength = float(plan["emissive"].get(key, 0.0))
        mel.set_material_instance_vector_parameter_value(mi, "Emissive", lin(rgb))
        mel.set_material_instance_scalar_parameter_value(mi, "EmissiveStrength", strength)
        mel.set_material_instance_scalar_parameter_value(mi, "Roughness", 0.35 if strength else 0.85)
        mel.update_material_instance(mi)
        unreal.EditorAssetLibrary.save_loaded_asset(mi)
        out[key] = mi
    return out


def _expr(mat, cls, x, y, **props):
    e = unreal.MaterialEditingLibrary.create_material_expression(mat, cls, x, y)
    for k, v in props.items():
        setp(e, k, v)
    return e


def auto_landscape_material(level, palette, textures=None):
    """Landscape auto-material: grass / rock / sand / snow blended by slope and height (no painting needed), the same
    rule as the browser engine and the Godot splat shader. textures: {"grass"|"rock"|"sand"|"snow": Texture2D}."""
    name = "M_GS_Landscape_%02d" % level
    mat = load(ROOT + "/Materials/" + name)
    if mat is not None:
        unreal.EditorAssetLibrary.delete_asset(ROOT + "/Materials/" + name)
    mel = unreal.MaterialEditingLibrary
    mat = asset_tools().create_asset(name, ROOT + "/Materials", unreal.Material, unreal.MaterialFactoryNew())
    textures = textures or {}

    def layer(key, rgb, y):
        tex = textures.get(key)
        tint = _expr(mat, unreal.MaterialExpressionVectorParameter, -1400, y, parameter_name=key.capitalize() + "Tint",
                     default_value=lin(rgb))
        if tex is None:
            return tint
        coords = _expr(mat, unreal.MaterialExpressionLandscapeLayerCoords, -1700, y + 60, mapping_scale=400.0)
        samp = _expr(mat, unreal.MaterialExpressionTextureSampleParameter2D, -1400, y + 60,
                     parameter_name=key.capitalize() + "Texture", texture=tex)
        mel.connect_material_expressions(coords, "", samp, "UVs")
        mul = _expr(mat, unreal.MaterialExpressionMultiply, -1150, y)
        mel.connect_material_expressions(samp, "RGB", mul, "A")
        white = _expr(mat, unreal.MaterialExpressionConstant3Vector, -1400, y + 140,
                      constant=unreal.LinearColor(1, 1, 1, 1))
        mel.connect_material_expressions(white, "", mul, "B")
        return mul
    grass = layer("grass", palette.get("ground", [0.3, 0.5, 0.25]), -600)
    rock = layer("rock", palette.get("stone", [0.45, 0.43, 0.42]), -350)
    sand = layer("sand", palette.get("sand", [0.78, 0.7, 0.5]), -100)
    snow = layer("snow", palette.get("snow", [0.92, 0.94, 0.97]), 150)
    # slope weight: clamp((1 - normal.z) * 3.5 - 0.35, 0, 1)
    nrm = _expr(mat, unreal.MaterialExpressionVertexNormalWS, -1400, 420)
    nz = _expr(mat, unreal.MaterialExpressionComponentMask, -1200, 420, r=False, g=False, b=True, a=False)
    mel.connect_material_expressions(nrm, "", nz, "")
    one = _expr(mat, unreal.MaterialExpressionConstant, -1200, 520, r=1.0)
    slope = _expr(mat, unreal.MaterialExpressionSubtract, -1000, 420)
    mel.connect_material_expressions(one, "", slope, "A")
    mel.connect_material_expressions(nz, "", slope, "B")
    k = _expr(mat, unreal.MaterialExpressionMultiply, -850, 420, const_b=3.5)
    mel.connect_material_expressions(slope, "", k, "A")
    kk = _expr(mat, unreal.MaterialExpressionSubtract, -700, 420, const_b=0.35)
    mel.connect_material_expressions(k, "", kk, "A")
    w_rock = _expr(mat, unreal.MaterialExpressionClamp, -550, 420)
    mel.connect_material_expressions(kk, "", w_rock, "")
    # height weights from world Z (metres)
    wpos = _expr(mat, unreal.MaterialExpressionWorldPosition, -1400, 650)
    wz = _expr(mat, unreal.MaterialExpressionComponentMask, -1200, 650, r=False, g=False, b=True, a=False)
    mel.connect_material_expressions(wpos, "", wz, "")
    metres = _expr(mat, unreal.MaterialExpressionDivide, -1000, 650, const_b=100.0)
    mel.connect_material_expressions(wz, "", metres, "A")
    water = palette.get("water_level")
    shore = _expr(mat, unreal.MaterialExpressionScalarParameter, -1000, 760, parameter_name="ShoreLevel",
                  default_value=float(water) + 0.35 if water is not None else -1000.0)
    sh = _expr(mat, unreal.MaterialExpressionSubtract, -850, 700)
    mel.connect_material_expressions(shore, "", sh, "A")
    mel.connect_material_expressions(metres, "", sh, "B")
    shk = _expr(mat, unreal.MaterialExpressionMultiply, -700, 700, const_b=2.5)
    mel.connect_material_expressions(sh, "", shk, "A")
    w_sand = _expr(mat, unreal.MaterialExpressionClamp, -550, 700)
    mel.connect_material_expressions(shk, "", w_sand, "")
    snow_line = _expr(mat, unreal.MaterialExpressionScalarParameter, -1000, 880, parameter_name="SnowLine",
                      default_value=float(palette.get("snow_line", 1000.0)))
    sn = _expr(mat, unreal.MaterialExpressionSubtract, -850, 850)
    mel.connect_material_expressions(metres, "", sn, "A")
    mel.connect_material_expressions(snow_line, "", sn, "B")
    snk = _expr(mat, unreal.MaterialExpressionMultiply, -700, 850, const_b=0.5)
    mel.connect_material_expressions(sn, "", snk, "A")
    w_snow = _expr(mat, unreal.MaterialExpressionClamp, -550, 850)
    mel.connect_material_expressions(snk, "", w_snow, "")
    # blend: grass -> sand (shore) -> snow (height) -> rock (slope)
    l1 = _expr(mat, unreal.MaterialExpressionLinearInterpolate, -350, -400)
    mel.connect_material_expressions(grass, "", l1, "A")
    mel.connect_material_expressions(sand, "", l1, "B")
    mel.connect_material_expressions(w_sand, "", l1, "Alpha")
    l2 = _expr(mat, unreal.MaterialExpressionLinearInterpolate, -200, -300)
    mel.connect_material_expressions(l1, "", l2, "A")
    mel.connect_material_expressions(snow, "", l2, "B")
    mel.connect_material_expressions(w_snow, "", l2, "Alpha")
    l3 = _expr(mat, unreal.MaterialExpressionLinearInterpolate, -50, -200)
    mel.connect_material_expressions(l2, "", l3, "A")
    mel.connect_material_expressions(rock, "", l3, "B")
    mel.connect_material_expressions(w_rock, "", l3, "Alpha")
    mel.connect_material_property(l3, "", unreal.MaterialProperty.MP_BASE_COLOR)
    rough = _expr(mat, unreal.MaterialExpressionConstant, -50, 50, r=0.92)
    mel.connect_material_property(rough, "", unreal.MaterialProperty.MP_ROUGHNESS)
    mel.recompile_material(mat)
    unreal.EditorAssetLibrary.save_loaded_asset(mat)
    return mat


def water_material(rgb):
    """The Water plugin's lake material when available, else a simple translucent water material."""
    for p in ("/Water/Materials/WaterSurface/Water_Material_Lake", "/Water/Materials/WaterSurface/Water_Material_Ocean"):
        m = load(p)
        if m is not None:
            return m
    path = ROOT + "/Materials/M_GS_Water"
    m = load(path)
    if m is not None:
        return m
    mel = unreal.MaterialEditingLibrary
    mat = asset_tools().create_asset("M_GS_Water", ROOT + "/Materials", unreal.Material, unreal.MaterialFactoryNew())
    setp(mat, "blend_mode", unreal.BlendMode.BLEND_TRANSLUCENT)
    setp(mat, "translucency_lighting_mode", unreal.TranslucencyLightingMode.TLM_SURFACE)
    col = _expr(mat, unreal.MaterialExpressionVectorParameter, -500, -100, parameter_name="WaterColor",
                default_value=lin(rgb))
    mel.connect_material_property(col, "", unreal.MaterialProperty.MP_BASE_COLOR)
    op = _expr(mat, unreal.MaterialExpressionConstant, -500, 100, r=0.78)
    mel.connect_material_property(op, "", unreal.MaterialProperty.MP_OPACITY)
    rough = _expr(mat, unreal.MaterialExpressionConstant, -500, 200, r=0.05)
    mel.connect_material_property(rough, "", unreal.MaterialProperty.MP_ROUGHNESS)
    mel.recompile_material(mat)
    unreal.EditorAssetLibrary.save_loaded_asset(mat)
    return mat


# ---------------- placement
KIND_NAMES = {"npc": "NPC"}


def kind(cls):
    """gs class -> label/folder stem: GS_<Kind>_### in Outliner folder Stark/<Kind>s."""
    return KIND_NAMES.get(cls, cls.capitalize())


def part_transform(o, part, uniform=None):
    """object + proxy part -> (location, rotator, scale) in UE units (see the module docstring for the mapping)."""
    s, yaw = float(o["s"]), float(o["yaw"])
    r = math.radians(yaw)
    if uniform is not None:
        return cm(o["x"], o["y"], o["z"]), rot(yaw), unreal.Vector(uniform, uniform, uniform)
    ox, oy, oz = [v * s for v in part["off"]]
    px = o["x"] + ox * math.cos(r) - oz * math.sin(r)
    pz = o["z"] + ox * math.sin(r) + oz * math.cos(r)
    sx, sy, sz = [v * s for v in part["size"]]
    return cm(px, o["y"] + oy, pz), rot(yaw, float(part.get("tilt", 0.0))), unreal.Vector(sz, sx, sy)


def _hism(label, folder, tags, mesh, material, xforms, collision=True):
    a = spawn(unreal.Actor, unreal.Vector(0, 0, 0), None, label, folder, tags)
    try:
        sds = unreal.get_engine_subsystem(unreal.SubobjectDataSubsystem)
        handles = sds.k2_gather_subobject_data_for_instance(a)
        params = unreal.AddNewSubobjectParams(parent_handle=handles[0],
                                              new_class=unreal.HierarchicalInstancedStaticMeshComponent,
                                              blueprint_context=None)
        handle, fail = sds.add_new_subobject(params)
        lib = unreal.SubobjectDataBlueprintFunctionLibrary
        c = lib.get_object(lib.get_data(handle))
        c.set_static_mesh(mesh)
        if material:
            c.set_material(0, material)
        if collision:
            c.set_collision_profile_name("BlockAll")
        for loc, r, scl in xforms:
            c.add_instance(unreal.Transform(location=loc, rotation=r, scale=scl), True)
        if c.get_instance_count() != len(xforms):
            raise RuntimeError("instance count mismatch")
        return [a]
    except Exception as e:
        warn("instancing unavailable (%s); placing individual actors" % e)
        destroy([a])
        return None


def place(cls, part_name, mesh, material, xforms, labels, tags, collision=True):
    """Spawn one StaticMeshActor per transform, or one instanced (HISM) actor for large counts."""
    folder = "Stark/" + kind(cls) + "s"
    if len(xforms) >= INSTANCE_MIN:
        got = _hism("GS_%ss_%s_Instanced" % (kind(cls), part_name), folder, tags, mesh, material, xforms, collision)
        if got:
            return got
    out = []
    for (loc, r, scl), label in zip(xforms, labels):
        a = spawn(unreal.StaticMeshActor, loc, r, label, folder, tags)
        c = a.static_mesh_component
        c.set_static_mesh(mesh)
        if material:
            c.set_material(0, material)
        if not collision:
            c.set_collision_enabled(unreal.CollisionEnabled.NO_COLLISION)
        a.set_actor_scale3d(scl)
        out.append(a)
    return out


def read_swap_map():
    rows = {}
    p = os.path.join(HERE, "proxy_swap_map.csv")
    if not os.path.isfile(p):
        return rows
    with open(p, encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            cls = (r.get("gs_class") or "").strip().lower()
            path = (r.get("asset_path") or "").strip().strip("'\"")
            if cls and path:
                if "'" in path:                          # "StaticMesh'/Game/x.x'" reference format
                    path = path.split("'")[1]
                try:
                    scale = float(r.get("scale") or 1.0)
                except ValueError:
                    scale = 1.0
                try:
                    zoff = float(r.get("z_offset_cm") or 0.0)
                except ValueError:
                    zoff = 0.0
                rows[cls] = {"path": path, "scale": scale, "zoff": zoff,
                             "random_yaw": (r.get("random_yaw") or "0").strip() in ("1", "true", "yes")}
    return rows


def read_metahuman_slots():
    out = {}
    p = os.path.join(HERE, "metahuman_slots.csv")
    if not os.path.isfile(p):
        return out
    with open(p, encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            nid = (r.get("npc_id") or "").strip()
            bp = (r.get("character_blueprint") or "").strip().strip("'\"")
            if nid and bp:
                out[nid] = bp.split("'")[1] if "'" in bp else bp
    return out


def swap_class(plan, cls, row):
    """Replace every proxy of one scenery class with a real asset (StaticMesh, Blueprint or, for ground, a Material).
    Gameplay classes keep their Stark World Engine actor and get the mesh in its ArtMesh slot instead."""
    asset = unreal.EditorAssetLibrary.load_asset(row["path"])
    if asset is None:
        warn("swap %s: asset not found: %s" % (cls, row["path"]))
        return 0
    asset_kind = class_name(asset)
    if cls == "ground":
        n = 0
        for a in gs_actors("GS_Terrain"):
            if "Landscape" in class_name(a):
                setp(a, "landscape_material", asset)
                n += 1
                continue
            c = comp(a, unreal.StaticMeshComponent)
            if c:
                c.set_material(0, asset)
                n += 1
        return n
    if cls in ("npc", "enemy", "item", "chest", "door", "portal", "checkpoint", "crystal") and runtime_ready():
        n = 0
        for a in gs_actors("GS_Class_" + cls):
            if asset_kind == "StaticMesh" and "StarkInteractable" in class_name(a):
                setp(a, "art_mesh", asset)
                setp(a, "art_scale", float(row["scale"]))
                n += 1
            elif "Blueprint" in asset_kind:
                try:
                    bp = unreal.EditorAssetLibrary.load_blueprint_class(row["path"])
                    setp(a, "visual_class", bp)
                    n += 1
                except Exception as e:
                    warn("swap %s: %s" % (cls, e))
        return n
    objs = [o for o in plan.get("objects", []) if o["cls"] == cls]
    if not objs:
        return 0
    destroy(gs_actors("GS_Class_" + cls))
    tags = ["GS_Class_" + cls, "GS_Real"]
    xforms, labels = [], []
    for o in objs:
        loc, r, scl = part_transform(o, None, uniform=float(o["s"]) * row["scale"])
        loc = unreal.Vector(loc.x, loc.y, loc.z + row["zoff"])
        if not row["random_yaw"]:
            r = rot(0.0)
        xforms.append((loc, r, scl))
        labels.append("GS_%s_%03d" % (kind(cls), o["i"]))
    if asset_kind == "StaticMesh":
        return len(place(cls, "Real", asset, None, xforms, labels, tags)) and len(objs)
    bp = None
    if "Blueprint" in asset_kind:
        try:
            bp = unreal.EditorAssetLibrary.load_blueprint_class(row["path"])
        except Exception:
            bp = None
    if bp is None:
        warn("swap %s: %s is a %s; use a StaticMesh or Blueprint" % (cls, row["path"], asset_kind or "unknown asset"))
        return 0
    for (loc, r, scl), label in zip(xforms, labels):
        a = spawn(bp, loc, r, label, "Stark/" + kind(cls) + "s", tags)
        a.set_actor_scale3d(scl)
    return len(objs)


def swap_all(plan):
    rows = read_swap_map()
    done = {}
    for cls, row in rows.items():
        try:
            done[cls] = swap_class(plan, cls, row)
        except Exception as e:
            warn("swap %s failed: %s" % (cls, e))
    slots = read_metahuman_slots()
    if slots and runtime_ready():
        n = 0
        for a in gs_actors("GS_Class_npc"):
            c = comp(a, unreal.StarkNpcComponent)
            nid = str(c.get_editor_property("npc_id")) if c else ""
            if nid in slots:
                try:
                    setp(a, "visual_class", unreal.EditorAssetLibrary.load_blueprint_class(slots[nid]))
                    n += 1
                except Exception as e:
                    warn("metahuman slot %s: %s" % (nid, e))
        done["metahuman_slots"] = n
    return done


# ---------------- terrain
def write_obj(path, verts, faces, uvs, name):
    with open(path, "w", encoding="ascii", newline="\n") as f:
        f.write("# Stark World Engine terrain\no %s\n" % name)
        for v in verts:
            f.write("v %.3f %.3f %.3f\n" % v)
        for t in uvs:
            f.write("vt %.4f %.4f\n" % t)
        for a, b, c in faces:
            f.write("f %d/%d %d/%d %d/%d\n" % (a, a, b, b, c, c))


def import_file(path, dest, name=None):
    """AssetImportTask (FBX/OBJ/glTF via Interchange, textures, WAV) -> list of imported objects."""
    t = unreal.AssetImportTask()
    for k, v in (("filename", path), ("destination_path", dest), ("automated", True), ("replace_existing", True),
                 ("save", True)):
        setp(t, k, v)
    if name:
        setp(t, "destination_name", name)
    asset_tools().import_asset_tasks([t])
    objs = []
    try:
        objs = list(t.get_objects() or [])
    except Exception:
        pass
    if not objs:
        try:
            objs = [unreal.EditorAssetLibrary.load_asset(str(p).split(".")[0]) for p in
                    (t.get_editor_property("imported_object_paths") or [])]
        except Exception:
            objs = []
    return [o for o in objs if o is not None]


def import_mesh(path, dest, name):
    for a in import_file(path, dest, name):
        if class_name(a) == "StaticMesh":
            return a
    for p in unreal.EditorAssetLibrary.list_assets(dest, False, False):
        if name in str(p):
            a = unreal.EditorAssetLibrary.load_asset(str(p).split(".")[0])
            if class_name(a) == "StaticMesh":
                return a
    return None


def calibrate():
    """Import a tiny probe OBJ to learn how this engine version maps OBJ axes -> UE axes."""
    os.makedirs(SAVED, exist_ok=True)
    p = os.path.join(SAVED, "GS_Probe.obj")
    write_obj(p, [(100.0, 300.0, 1000.0), (200.0, 300.0, 1000.0), (100.0, 500.0, 1000.0), (100.0, 300.0, 1400.0)],
              [(1, 2, 3), (1, 2, 4), (1, 3, 4), (2, 3, 4)], [(0, 0)] * 4, "GS_Probe")
    m = import_mesh(p, ROOT + "/Terrain", "SM_GS_Probe")
    if m is None:
        raise RuntimeError("OBJ import produced no StaticMesh")
    b = m.get_bounds()
    cs = [float(b.origin.x), float(b.origin.y), float(b.origin.z)]
    es = [float(b.box_extent.x), float(b.box_extent.y), float(b.box_extent.z)]
    order = sorted(range(3), key=lambda i: es[i])
    f = es[order[0]] / 50.0
    if f <= 0:
        raise RuntimeError("degenerate probe bounds %s" % es)
    mapping = [None, None, None]
    for k, i in enumerate(order):
        half, centre = (50.0, 100.0, 200.0)[k] * f, (150.0, 400.0, 1200.0)[k] * f
        if abs(es[i] - half) > 0.2 * half or abs(abs(cs[i]) - centre) > 0.2 * centre:
            raise RuntimeError("probe bounds not understood: origin %s extent %s" % (cs, es))
        mapping[i] = (k, 1.0 if cs[i] > 0 else -1.0)
    try:
        unreal.EditorAssetLibrary.delete_asset(m.get_path_name().split(".")[0])
    except Exception:
        pass
    return mapping, f


def terrain_mesh(plan):
    """Fallback ground (no Landscape helper): build + import a Nanite terrain mesh that lands exactly on the plan
    heights. -> StaticMesh or None."""
    t = plan["terrain"]
    res, span, hs = int(t["res"]), float(t["span"]), t["heights"]
    mapping, f = calibrate()
    half, cell = span / 2.0, span / (res - 1)

    def src(X, Y, Z):
        out = [0.0, 0.0, 0.0]
        for i, P in enumerate((X, Y, Z)):
            k, s = mapping[i]
            out[k] = P / (s * f)
        return tuple(out)

    verts, uvs = [], []
    for iz in range(res):
        for ix in range(res):
            x, z = -half + ix * cell, -half + iz * cell
            verts.append(src(-z * 100.0, x * 100.0, hs[iz * res + ix] * 100.0))      # same mapping as cm()
            uvs.append((x / 4.0, z / 4.0))
    # winding: the triangle normal in the OBJ (right-handed, CCW) must point along the engine's +Z after import
    up = [0.0, 0.0, 0.0]
    k, s = mapping[2]
    up[k] = s
    a, b, c = src(0, 0, 0), src(-100, 0, 0), src(0, 100, 0)        # plan +z -> UE -X, plan +x -> UE +Y
    u = [b[j] - a[j] for j in range(3)]
    v = [c[j] - a[j] for j in range(3)]
    n = (u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0])
    flip = sum(n[j] * up[j] for j in range(3)) > 0
    faces = []
    for iz in range(res - 1):
        for ix in range(res - 1):
            i0 = iz * res + ix + 1
            i1, i2, i3 = i0 + 1, i0 + res, i0 + res + 1
            for tri in ((i0, i1, i2), (i1, i3, i2)):
                faces.append((tri[0], tri[2], tri[1]) if flip else tri)
    p = os.path.join(SAVED, "GS_Terrain_%02d.obj" % plan.get("level", 0))
    write_obj(p, verts, faces, uvs, "SM_GS_Terrain")
    m = import_mesh(p, ROOT + "/Terrain", "SM_GS_Terrain_%02d" % plan.get("level", 0))
    if m is None:
        raise RuntimeError("terrain import failed")
    e = m.get_bounds().box_extent
    if abs(float(e.x) - half * 100.0) > 0.05 * half * 100.0 or abs(float(e.y) - half * 100.0) > 0.05 * half * 100.0:
        raise RuntimeError("terrain bounds %s do not match span %s m" % (e, span))
    enable_nanite(m)
    try:
        bs = m.get_editor_property("body_setup")
        bs.set_editor_property("collision_trace_flag", unreal.CollisionTraceFlag.CTF_USE_COMPLEX_AS_SIMPLE)
    except Exception as ex:
        warn("terrain collision: %s" % ex)
    unreal.EditorAssetLibrary.save_loaded_asset(m)
    return m


def enable_nanite(mesh):
    """StaticMeshEditorSubsystem.get/set_nanite_settings (UE 5.4)."""
    try:
        sme = unreal.get_editor_subsystem(unreal.StaticMeshEditorSubsystem)
        ns = sme.get_nanite_settings(mesh)
        ns.set_editor_property("enabled", True)
        sme.set_nanite_settings(mesh, ns, True)
        return True
    except Exception as ex:
        warn("nanite on %s: %s" % (class_name(mesh), ex))
        return False


def landscape_size(span):
    """Vertex count per side for a real Landscape: 253 (4x4 components of 63 quads) or 505 for big levels."""
    return 253 if span <= 200.0 else 505


def terrain_height(t, x, z):
    """Plan height at (x, z) from the plan's terrain description (browser formula when kind == stark)."""
    if t.get("kind") == "stark":
        s = float(t["seed"])
        v = (math.sin(x * 0.13 + s) * 0.6 + math.cos(z * 0.11 + s * 0.7) * 0.6 + math.sin((x + z) * 0.05 + s) * 0.8
             + math.cos(x * 0.045 - z * 0.06 + s * 0.4) * 0.9 + math.sin(x * 0.29 + z * 0.23 + s * 1.3) * 0.18)
        h = float(t["amp"]) * v * 0.55
        d = max(abs(x), abs(z)) - float(t["size"])
        if d > 0:
            tt = min(1.0, d / float(t["margin"]))
            h += float(t["edge"]) * tt * tt * (3 - 2 * tt)
        return h
    res, span, hs = int(t["res"]), float(t["span"]), t["heights"]
    half, cell = span / 2.0, span / (res - 1)
    gx = min(max((x + half) / cell, 0.0), res - 1.0001)
    gz = min(max((z + half) / cell, 0.0), res - 1.0001)
    x0, z0 = int(gx), int(gz)
    tx, tz = gx - x0, gz - z0
    a = hs[z0 * res + x0] + (hs[z0 * res + x0 + 1] - hs[z0 * res + x0]) * tx
    b = hs[(z0 + 1) * res + x0] + (hs[(z0 + 1) * res + x0 + 1] - hs[(z0 + 1) * res + x0]) * tx
    return a + (b - a) * tz


def landscape_heights(plan):
    """-> (16-bit heights row-major over UE X then Y, size, location cm, scale) for StarkEditorLibrary."""
    t = plan["terrain"]
    span = float(t["span"])
    n = landscape_size(span)
    cell = span / (n - 1)
    half = span / 2.0
    vals = []
    for iy in range(n):                  # UE Y = plan x
        x = -half + iy * cell
        for ix in range(n):              # UE X = -plan z
            z = half - ix * cell
            vals.append(max(0, min(65535, int(round(32768 + terrain_height(t, x, z) * 128.0)))))
    # Landscape data is indexed [y * SizeX + x]; we built rows by Y, columns by X
    loc = unreal.Vector(-half * 100.0, -half * 100.0, 0.0)
    scale = unreal.Vector(cell * 100.0, cell * 100.0, 100.0)
    return vals, n, loc, scale


def write_png16(path, w, h, vals):
    raw = b"".join(b"\x00" + struct.pack(">%dH" % w, *vals[r * w:(r + 1) * w]) for r in range(h))

    def chunk(kind_, data):
        return struct.pack(">I", len(data)) + kind_ + data + struct.pack(">I", zlib.crc32(kind_ + data) & 0xffffffff)
    with open(path, "wb") as f:
        f.write(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 16, 0, 0, 0, 0))
                + chunk(b"IDAT", zlib.compress(raw, 9)) + chunk(b"IEND", b""))


def heightmap_png(plan, size=505):
    """16-bit heightmap for Landscape > Import from File (Z scale 100 => 1/128 m per unit around 32768)."""
    t = plan["terrain"]
    span = float(t["span"])
    vals = []
    for v in range(size):                # image rows = Landscape Y = plan x
        for u in range(size):            # image columns = Landscape X = -plan z
            x = -span / 2.0 + v / (size - 1.0) * span
            z = span / 2.0 - u / (size - 1.0) * span
            vals.append(max(0, min(65535, int(round(32768 + terrain_height(t, x, z) * 128.0)))))
    os.makedirs(SAVED, exist_ok=True)
    p = os.path.join(SAVED, "GS_Heightmap_%02d_%d.png" % (plan.get("level", 0), size))
    write_png16(p, size, size, vals)
    xy = span * 100.0 / (size - 1)
    info = {"file": os.path.relpath(p, PROJECT), "location_cm": [-span * 50.0, -span * 50.0, 0.0], "scale": [xy, xy, 100.0]}
    log("Landscape import file: %s  location %s  scale %s" % (info["file"], info["location_cm"], info["scale"]))
    return info


def flatten(plan):
    """Terrain fell back to a flat plane: drop every height in the plan to ground level 0."""
    for o in plan["objects"]:
        o["y"] = 0.0
    for L in plan["lights"]:
        L["y"] = L["y"] - L.get("ground", 0.0)
    for m in plan["markers"]:
        m["y"] = 0.0
    plan["spawn"]["y"] = 0.0
    for c in plan["cameras"]:
        c["pos"][1] -= c.get("ground", 0.0)
        c["target"][1] -= c.get("tground", 0.0)


# ---------------- art library (glTF 2.0 + stark_assets.json), sounds, data assets
def import_art():
    """Import every library file listed in Content/Python/stark_assets.json (copied under StarkAssets/) with
    Interchange (glTF -> static meshes + PBR materials). -> {gs class: StaticMesh / Texture2D}"""
    p = os.path.join(HERE, "stark_assets.json")
    if not os.path.isfile(p):
        return {}
    man = load_json(p)
    by_id = {}
    for a in man.get("assets", []):
        rel = str(a.get("file", ""))
        if not rel.startswith("StarkAssets/"):
            continue
        src = os.path.join(PROJECT, *rel.split("/"))
        if not os.path.isfile(src):
            warn("art file missing: %s" % rel)
            continue
        dest = ROOT + "/Art/" + a["id"]
        objs = import_file(src, dest)
        mesh = next((o for o in objs if class_name(o) == "StaticMesh"), None)
        tex = next((o for o in objs if "Texture" in class_name(o)), None)
        if mesh is not None:
            enable_nanite(mesh)
        by_id[a["id"]] = mesh or tex
        if mesh is None and tex is None:
            warn("art %s imported nothing usable" % a["id"])
    out = {}
    for cls, aid in (man.get("classes") or {}).items():
        if by_id.get(aid) is not None:
            out[cls] = by_id[aid]
    return out


def synth_wav(path, p, rate=22050):
    """The browser engine's tiny sound synth (sfxSamples) -> 16-bit mono WAV."""
    import random
    n = max(1, int(float(p.get("dur", 0.3)) * rate))
    rng = random.Random(int(p.get("seed", 7)))
    ph, f, out = 0.0, float(p.get("freq", 440)), []
    for i in range(n):
        t = i / float(n)
        fr = max(20.0, f * (1 + float(p.get("slide", 0)) * t))
        ph += fr / rate
        w = p.get("wave", "square")
        if w == "square":
            v = 1.0 if (ph % 1) < 0.5 else -1.0
        elif w == "saw":
            v = 2 * (ph % 1) - 1
        elif w == "sine":
            v = math.sin(2 * math.pi * ph)
        else:
            v = rng.random() * 2 - 1
        nz = float(p.get("noise", 0) or 0)
        if nz:
            v = v * (1 - nz) + (rng.random() * 2 - 1) * nz
        v *= min(1.0, t * 40) * ((1 - t) ** float(p.get("decay", 2))) * float(p.get("vol", 0.5))
        out.append(int(max(-1.0, min(1.0, v)) * 32767))
    with wave.open(path, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(rate)
        wf.writeframes(struct.pack("<%dh" % len(out), *out))


def build_sounds(game):
    out = {}
    d = os.path.join(SAVED, "sfx")
    os.makedirs(d, exist_ok=True)
    for name, p in (game.get("sfx") or {}).items():
        try:
            fp = os.path.join(d, "SFX_GS_%s.wav" % name)
            synth_wav(fp, p)
            snd = next((o for o in import_file(fp, ROOT + "/Audio") if "Sound" in class_name(o)), None)
            if snd is not None:
                out[name] = snd
        except Exception as e:
            warn("sound %s: %s" % (name, e))
    return out


def build_data_assets(game, sounds):
    """One data asset per item / enemy / NPC / quest / dialogue / level + DA_StarkGame (needs the runtime)."""
    if not runtime_ready():
        warn("Stark World Engine Runtime plugin not loaded: data assets skipped (the runtime reads stark_game_ue.json)")
        return None
    ue = json.loads(load_game_ue_text())
    folder = ROOT + "/Data"
    groups = (("Items", "Item", unreal.StarkItemAsset, "Id"), ("Enemies", "Enemy", unreal.StarkEnemyAsset, "Kind"),
              ("Npcs", "Npc", unreal.StarkNpcAsset, "Id"), ("Quests", "Quest", unreal.StarkQuestAsset, "Id"),
              ("Dialogues", "Dialogue", unreal.StarkDialogueAsset, "Id"), ("Levels", "Level", unreal.StarkLevelAsset, "Index"))
    lists = {}
    for key, stem, cls, idf in groups:
        lists[key] = []
        for rec in ue.get(key, []):
            fac = unreal.DataAssetFactory()
            fac.set_editor_property("data_asset_class", cls)
            nm = "DA_%s_%s" % (stem, "".join(ch if ch.isalnum() else "_" for ch in str(rec.get(idf)))[:48])
            a = new_asset(nm, folder + "/" + key, cls, fac)
            if a is None or not a.import_json(json.dumps(rec)):
                warn("data asset %s failed" % nm)
                continue
            unreal.EditorAssetLibrary.save_loaded_asset(a)
            lists[key].append(a)
    fac = unreal.DataAssetFactory()
    fac.set_editor_property("data_asset_class", unreal.StarkGameData)
    ga = new_asset("DA_StarkGame", folder, unreal.StarkGameData, fac)
    ga.import_header_json(json.dumps({"Title": ue.get("Title"), "Author": ue.get("Author"), "Story": ue.get("Story"),
                                      "SaveKey": ue.get("SaveKey"), "Rules": ue.get("Rules")}))
    for key, _, _, _ in groups:
        setp(ga, key.lower(), lists[key])
    if sounds:
        setp(ga, "sounds", {k: v for k, v in sounds.items()})
    unreal.EditorAssetLibrary.save_loaded_asset(ga)
    return ga


# ---------------- PCG ambient scatter (grass, bushes, pebbles on the landscape)
def pcg_graph(level, meshes, density):
    """PCG graph: graph input (Landscape) -> Surface Sampler -> Static Mesh Spawner (weighted meshes) -> output.
    PCGGraph.add_node_of_type / add_edge, PCGStaticMeshSpawnerSettings.set_mesh_selector_type (UE 5.4)."""
    name = "PCG_GS_Ambient_%02d" % level
    path = ROOT + "/PCG/" + name
    if load(path) is not None:
        unreal.EditorAssetLibrary.delete_asset(path)
    graph = asset_tools().create_asset(name, ROOT + "/PCG", unreal.PCGGraph, unreal.PCGGraphFactory())
    sampler, s_settings = graph.add_node_of_type(unreal.PCGSurfaceSamplerSettings)
    setp(s_settings, "points_per_squared_meter", float(density))
    setp(s_settings, "looseness", 1.0)
    spawner, m_settings = graph.add_node_of_type(unreal.PCGStaticMeshSpawnerSettings)
    m_settings.set_mesh_selector_type(unreal.PCGMeshSelectorWeighted)
    sel = m_settings.get_editor_property("mesh_selector_parameters")
    entries = []
    for mesh, weight in meshes:
        e = unreal.PCGMeshSelectorWeightedEntry(int(weight))
        d = e.get_editor_property("descriptor")
        d.set_editor_property("static_mesh", mesh)
        e.set_editor_property("descriptor", d)
        entries.append(e)
    setp(sel, "mesh_entries", entries)
    graph.add_edge(graph.get_input_node(), "Landscape", sampler, "Surface")
    graph.add_edge(sampler, "Out", spawner, "In")
    graph.add_edge(spawner, "Out", graph.get_output_node(), "Out")
    unreal.EditorAssetLibrary.save_loaded_asset(graph)
    return graph


def save_all():
    try:
        level_sub().save_current_level()
    except Exception as e:
        warn("save level: %s" % e)
    try:
        unreal.EditorAssetLibrary.save_directory(ROOT, False, True)
    except Exception as e:
        warn("save assets: %s" % e)


def write_report(extra):
    REPORT.update(extra)
    os.makedirs(SAVED, exist_ok=True)
    with open(os.path.join(SAVED, "build_report.json"), "w", encoding="utf-8") as f:
        json.dump(REPORT, f, indent=1, default=str)


def write_state(ok):
    os.makedirs(SAVED, exist_ok=True)
    with open(os.path.join(SAVED, "build_state.json"), "w", encoding="utf-8") as f:
        json.dump({"ok": bool(ok), "hash": content_hash(), "version": BUILD_VERSION}, f)


def build_is_current():
    p = os.path.join(SAVED, "build_state.json")
    try:
        s = load_json(p)
        return bool(s.get("ok")) and s.get("hash") == content_hash()
    except (OSError, ValueError):
        return False
